% 自編假位法：以函數殘差停止，不使用區間半寬當誤差界
f = @(x) x.^2 - 2; % 定義連續函數
xl = 1; xu = 2; % 初始包根區間
tolerance = 1e-4; % 函數殘差容許值
maxIterations = 100; % 有限的迭代上限
validateattributes(xl, {'double'}, {'scalar','real','finite'});
validateattributes(xu, {'double'}, {'scalar','real','finite','>',xl});
validateattributes(tolerance, {'double'}, {'scalar','real','finite','positive'});
validateattributes(maxIterations, {'double'}, {'scalar','integer','>=',1,'<=',10000});
fl = f(xl); fu = f(xu); % 端點函數值
if ~isreal(fl) || ~isreal(fu) || ~isfinite(fl) || ~isfinite(fu)
    error('FalsePosition:NonFinite', '端點函數值必須是有限實數。');
end
history = zeros(0,5); % 欄位：k、xl、xu、xr、f(xr)
converged = false; % 成功旗標
if fl == 0
    xr = xl; fr = fl; converged = true; % 左端點根
elseif fu == 0
    xr = xu; fr = fu; converged = true; % 右端點根
elseif sign(fl) == sign(fu)
    error('FalsePosition:Bracket', '端點非零且同號，包根條件不成立。');
end
for k = 1:maxIterations
    if converged, break; end % 端點已為根時不做插值
    denominator = fu-fl; % 插值分母
    if ~isfinite(denominator) || abs(denominator) <= eps(max(abs([fl,fu])))
        error('FalsePosition:Denominator', '插值分母無效或太小。');
    end
    xr = xl-fl*(xu-xl)/denominator; % 割線與 x 軸交點
    if ~isfinite(xr)
        error('FalsePosition:NonFinite', '插值點非有限值。');
    end
    fr = f(xr); % 新近似值的函數殘差
    if ~isreal(fr) || ~isfinite(fr)
        error('FalsePosition:NonFinite', '插值點函數值非有限實數。');
    end
    history(end+1,:) = [k,xl,xu,xr,fr]; % 保留更新前狀態
    fprintf('%d: xl=%.12g, xu=%.12g, xr=%.12g, f=%.12e\n',k,xl,xu,xr,fr);
    if abs(fr) <= tolerance
        converged = true; break; % 殘差達標才回報成功
    end
    if xr <= xl || xr >= xu
        error('FalsePosition:Precision', '浮點停滯或插值點離開區間，殘差尚未達標。');
    end
    if sign(fl) ~= sign(fr)
        xu = xr; fu = fr; % 保留左側異號子區間
        fprintf('保留 [xl,xr]，更新 xu。\n');
    else
        xl = xr; fl = fr; % 保留右側異號子區間
        fprintf('保留 [xr,xu]，更新 xl。\n');
    end
end
if ~converged
    error('FalsePosition:MaxIterations', '已達迭代上限，尚未收斂至指定條件。');
end
fprintf('近似根 %.12g，殘差 %.12e，迭代 %d 次\n',xr,fr,size(history,1));
